1	/**
2	 * Guards the contract between the `expert-review` agent, which returns a scored plan
3	 * review, and `pipeline.md`, which aggregates a panel of them into the plan's single score.
4	 *
5	 * The reason this guard exists: the agent repeatedly returned confident reviews built on
6	 * file contents it had never read, reporting no tool use, and its own prose prohibition
7	 * against doing so did not stop it. The fix is not a stronger instruction — it is a
8	 * declared `grounding` field the parent can screen, and a parent that discards rather
9	 * than averages a review that fails the screen. Both halves have to stay in place for
10	 * either to be worth anything, and they live in two prompt files with no import between
11	 * them, so nothing but a test relates them.
12	 *
13	 * Three properties are load-bearing:
14	 *
15	 * 1. The field list the agent emits matches the one the pipeline says it receives. The
16	 *    field names are parsed from the agent's own output table rather than hardcoded, so
17	 *    renaming one fails here instead of silently dropping from the screen.
18	 * 2. The pipeline states the discard rule and every condition that triggers it. A
19	 *    condition quietly deleted turns the screen back into an average-everything step.
20	 * 3. The pipeline refuses to present a shrunken panel as a consensus. Two of five
21	 *    reviewers failing is the observed case, and reporting the survivor's score as a
22	 *    panel aggregate is how that becomes invisible.
23	 *
24	 * What this CANNOT prove: that the screen runs, or that a reviewer declares its grounding
25	 * honestly — a fabricated `grounding` entry is still possible and is exactly why the
26	 * pipeline also screens for the no-tool-use contradiction rather than trusting the field
27	 * alone. CI sees text in a file, nothing more.
28	 */
29	import { readFile } from "node:fs/promises";
30	import { join } from "node:path";
31	
32	import { describe, expect, test } from "bun:test";
33	
34	const actionDir = join(import.meta.dirname, "..");
35	const repoRoot = join(actionDir, "..", "..", "..");
36	const autopilotDir = join(repoRoot, "claude-plugins/autopilot");
37	
38	const [agent, pipeline, chapter] = await Promise.all([
39	  readFile(join(autopilotDir, "agents/expert-review.md"), "utf8"),
40	  readFile(join(autopilotDir, "skills/plan/references/pipeline.md"), "utf8"),
41	  readFile(join(repoRoot, "docs/05-plan-run-skills.md"), "utf8"),
42	]);
43	
44	/**
45	 * The `| \`field\` |` rows of the agent's Phase 4 output table, sliced to that section so
46	 * the five-dimension rubric table above it does not leak in.
47	 */
48	function outputFields(source: string): string[] {
49	  const section = source.split("## Phase 4: Output")[1]?.split("Example (illustrative")[0] ?? "";
50	  return [...section.matchAll(/^\|\s*`(\w+)`/gm)].map((row) => row[1]);
51	}
52	
53	/** The backticked names on the pipeline's "Each returns JSON (…)" line. */
54	function pipelineFields(source: string): string[] {
55	  const line = source.split("\n").find((l) => l.startsWith("Each returns JSON ("));
56	  return [...(line ?? "").matchAll(/`(\w+)`/g)].map((m) => m[1]);
57	}
58	
59	/**
60	 * Top-level keys of the `expert-review` payload sketch in chapter 5's sub-agent contract
61	 * list — a third copy of the same contract, and the one that already drifted once.
62	 * Nested keys inside `dimensions{…}` are stripped so only the outer shape is compared.
63	 */
64	function chapterFields(source: string): string[] {
65	  const line = source.split("\n").find((l) => l.startsWith("- `expert-review` →"));
66	  const body = (line ?? "").replace(/(\w)\{[^{}]*\}/g, "$1");
67	  return [...body.matchAll(/[{,]\s*(\w+)/g)].map((m) => m[1]);
68	}
69	
70	const declared = outputFields(agent);
71	
72	describe("expert review contract", () => {
73	  test("the agent's output table is parseable and non-trivial", () => {
74	    expect(declared.length).toBeGreaterThan(4);
75	    expect(declared).toContain("findings");
76	  });
77	
78	  test("the agent declares a grounding field", () => {
79	    expect(declared).toContain("grounding");
80	  });
81	
82	  test("grounding is required, not optional", () => {
83	    const row = agent.split("\n").find((l) => /^\|\s*`grounding`/.test(l)) ?? "";
84	    expect(`grounding row: ${row}`).toContain("Never empty");
85	  });
86	
87	  test("the example payload carries grounding, so the shape is copyable", () => {
88	    const example = agent.split("```json")[1]?.split("```")[0] ?? "";
89	    expect(example).toContain('"grounding"');
90	  });
91	
92	  test("the pipeline receives exactly the fields the agent emits", () => {
93	    expect(pipelineFields(pipeline).sort()).toEqual([...declared].sort());
94	  });
95	
96	  test("chapter 5 documents exactly the fields the agent emits", () => {
97	    expect(chapterFields(chapter).sort()).toEqual([...declared].sort());
98	  });
99	
100	  test("chapter 5 records that an ungrounded review is discarded, not averaged", () => {
101	    expect(chapter).toContain("discarded rather than averaged");
102	  });
103	
104	  test.each([
105	    ["empty grounding", "`grounding` is absent or empty"],
106	    ["unparseable report", "not parseable as the JSON contract"],
107	    ["no-tool-use contradiction", "reported no tool use"],
108	  ])("the pipeline names the %s discard condition", (_label, needle) => {
109	    expect(pipeline).toContain(needle);
110	  });
111	
112	  test("the pipeline discards rather than averages", () => {
113	    const [, screen = ""] = pipeline.split("Discard an ungrounded review");
114	    expect(screen).toContain("Name every discard");
115	    expect(screen).toContain("never silently shrink the panel");
116	  });
117	
118	  test("a shrunken panel is not reported as a consensus", () => {
119	    expect(pipeline).toContain("single surviving reviewer is a single opinion");
120	    expect(pipeline).toContain("report that the plan is unreviewed");
121	  });
122	
123	  /**
124	   * The recorded score line names the weakest dimension because the aggregate alone
125	   * says how good the panel thought the plan was, not what to double-check when
126	   * executing it — and nothing reconstructs that later.
127	   */
128	  test("the recorded score line carries the weakest dimension", () => {
129	    expect(pipeline).toContain("weakest:");
130	    expect(pipeline).toContain("weakest dimension");
131	  });
132	
133	  test("the review step gates nothing", () => {
134	    expect(pipeline).toContain("never a gate");
135	    expect(pipeline).not.toContain("Scoring target");
136	    expect(pipeline).not.toMatch(/at most \w+ passes/);
137	  });
138	
139	  test("chapter 5 documents the same recorded score line", () => {
140	    expect(chapter).toContain("weakest dimension");
141	  });
142	
143	  test("the agent still forbids asserting unread file contents", () => {
144	    expect(agent).toContain("an inferred file listing is a fabrication");
145	    expect(agent).toContain("Do not list a file you did not open");
146	  });
147	});
